import React, { useEffect, useState } from "react";
import { getDailyBoxOffice } from "../api/boxofficeApi";
import { getPosterFromTMDB } from "../api/tmdbApi";
import MovieCard from "../components/MovieCard";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);

      try {
        // 어제 날짜 생성 (KOFIC API는 당일 데이터 없음)
        const today = new Date();
        today.setDate(today.getDate() - 1);
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, "0");
        const dd = String(today.getDate()).padStart(2, "0");
        const targetDt = `${yyyy}${mm}${dd}`; // "yyyymmdd"

        // 🎯 KOFIC 일별 박스오피스 데이터
        const boxOfficeList = await getDailyBoxOffice(targetDt);

        // 포스터 포함 데이터 가공
        const enrichedMovies = await Promise.all(
          boxOfficeList.map(async (movie, index) => {
            const year = movie.openDt?.substring(0, 4) || "";

            const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
              nation: movie.nationAlt, // 국가 정보 사용
            });

            return {
              id: index,
              title: movie.movieNm,
              poster_path:
                posterUrl || "https://via.placeholder.com/120x170?text=No+Image",
              description: `📅 개봉일: ${movie.openDt || "N/A"}\n👥 누적 관객: ${parseInt(
                movie.audiAcc
              ).toLocaleString()}명\n🎟️ 일일 관객: ${parseInt(
                movie.audiCnt
              ).toLocaleString()}명\n🎬 스크린 수: ${movie.scrnCnt}`,
            };
          })
        );

        setMovies(enrichedMovies);
      } catch (error) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchBoxOffice();
  }, []);

  if (loading) return <div>로딩 중...</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>📊 일별 박스오피스</h1>
      <div style={styles.movieGrid}>
        {movies.map((movie) => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
    padding: "2rem",
    boxSizing: "border-box",
  },
  title: {
    fontSize: "2.5rem",
    textAlign: "center",
    marginBottom: "3rem",
    fontWeight: "bold",
  },
  movieGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(3, 1fr)",
    columnGap: "2rem",
    rowGap: "3rem",
  },
};

export default HomePage;
